INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 5, 'theory', 'Quiz: sharding');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 5, 0, 'How does a shard differ from a replica?', '["It doesn''t", "A shard stores part of the data, a replica a full copy", "A replica stores part of the data, a shard a copy", "A shard is only needed for reads"]', 1, 'Shards divide data and writes among machines, while replicas copy all the data for reads and reliability.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 5, 1, 'Why is range sharding by an auto-increment ID a bad idea?', '["The IDs are too long", "All new records land in the last range, one shard", "Ranges can''t be stored", "A hash is better than a range in every case"]', 1, 'A monotonic key creates a hot spot: the last shard takes all the writes while the others sit idle.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 5, 2, 'What does consistent hashing give you when a new node is added?', '["Only a small share of keys moves", "All the data moves", "No data moves at all", "There are fewer nodes"]', 0, 'On the ring, the new node takes keys from its neighbor; the rest stay in place, so about 1/N of the data moves.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 5, 3, 'What happens to a query that doesn''t contain the shard key?', '["It goes to a random shard", "It is sent to all shards and the answers are merged", "It is rejected", "It goes to the leader"]', 1, 'This is scatter-gather: slower, it loads every shard, and its latency equals that of the slowest one.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 5, 4, 'What should you do before sharding?', '["Nothing: shard right away", "Indexes, cache, replicas, archiving, and partitioning", "Buy a server twice as powerful and forget it", "Turn off transactions"]', 1, 'Sharding is a last resort: it complicates queries, transactions, and operations.');
